import React, { useEffect, useState } from "react";

function ComplaintList({ complaints }) {
  const [complaintData, setComplaintData] = useState([]);

  // Fetch complaints from backend on first load
  useEffect(() => {
    fetch("http://localhost:8080/api/complaints")
      .then((response) => response.json())
      .then((data) => setComplaintData(data))
      .catch((error) => console.error("Error fetching complaints:", error));
  }, []);

  // Update when new complaints come from parent (App.js)
  useEffect(() => {
    if (complaints && complaints.length > 0) {
      setComplaintData(complaints);
    }
  }, [complaints]);

  return (
    <div>
      <h2>Complaints List</h2>
      <ul>
        {complaintData.map((complaint) => (
          <li key={complaint.id}>
            <strong>{complaint.category}</strong>: {complaint.description} (
            {complaint.status})
          </li>
        ))}
      </ul>
    </div>
  );
}

export default ComplaintList;
